                <>
                  <RefreshCw className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                  同步中...
                </>
              ) : (
                <>
                  <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
                  同步
                </>
              )}
            </Button>
          </div>
        </div>

        {/* Sync Result Alert */}
        {syncResult && (
          <Alert variant={syncResult.error ? "destructive" : "default"} data-testid="sync-result">
