    shares: 18.18,
    status: "FILLED",
    exit_type: null,
    created_at: "2026-02-17T10:00:00Z",
  },
  {
    id: 2,
    market_id: "market-2",
    trade_type: "SELL_NO",
    mode: "PAPER",
    amount: 5.0,
    price: 0.70,
    shares: 7.14,
    status: "FILLED",
    exit_type: null,
    created_at: "2026-02-17T11:00:00Z",
