    id: 3,
    market_id: "market-3",
    trade_type: "BUY_NO",
    mode: "LIVE",
    amount: 20.0,
    price: 0.30,
    shares: 66.67,
    status: "PENDING",
    exit_type: null,
    created_at: "2026-02-17T12:00:00Z",
  },
];

describe("Trades Page", () => {
  beforeEach(() => {
    vi.clearAllMocks();
