      const tradesWithNullShares: TradeListItem[] = [
        {
          id: 1,
          market_id: "market-1",
          trade_type: "BUY_YES",
          mode: "PAPER",
          amount: 10.0,
          price: 0.55,
          shares: null,
          status: "FILLED",
          created_at: "2026-02-17T10:00:00Z",
        },
