import { useState, useMemo } from "react";
import { DashboardLayout } from "@/components/layout/DashboardLayout";
import { useTrades } from "@/hooks/useTrades";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { cn } from "@/lib/utils";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import {
  Pagination, PaginationContent, PaginationItem, PaginationLink,
  PaginationNext, PaginationPrevious, PaginationEllipsis,
} from "@/components/ui/pagination";
import { AlertCircle } from "lucide-react";
import { ExitTypeBadge } from "@/components/trades/ExitTypeBadge";

type TypeFilter = "all" | "buy" | "sell";
const PAGE_SIZE = 20;

/**
 * Trades Page - Story 7.9
 *
 * Trading mode (paper/live) is now determined by backend TRADING_MODE setting.
 * No manual sync or mode filter needed.
 */
const Trades = () => {
  const [typeFilter, setTypeFilter] = useState<TypeFilter>("all");
  const [page, setPage] = useState(1);

  // Fetch trades - mode is determined by backend settings
  const { data, isLoading, error } = useTrades({
    type_filter: typeFilter === "all" ? undefined : typeFilter,
  });

  // Filter by type in memory (backend also supports this)
  const filtered = useMemo(() => {
    const trades = data?.items ?? [];
    return trades.filter((t) => {
      if (typeFilter === "buy" && !t.trade_type.startsWith("BUY")) return false;
      if (typeFilter === "sell" && !t.trade_type.startsWith("SELL")) return false;
      return true;
    });
  }, [data?.items, typeFilter]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const paged = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  // Reset page when filter changes
  const handleTypeFilter = (t: TypeFilter) => { setTypeFilter(t); setPage(1); };

  const FilterButton = ({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) => (
    <Button variant="ghost" size="sm" onClick={onClick}
      className={cn("text-xs h-8 px-3 rounded-md", active ? "bg-primary/15 text-primary" : "text-muted-foreground hover:text-foreground")}>
      {children}
    </Button>
  );

  const pageNumbers = useMemo(() => {
    const pages: (number | "ellipsis")[] = [];
    if (totalPages <= 5) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1);
      if (currentPage > 3) pages.push("ellipsis");
      for (let i = Math.max(2, currentPage - 1); i <= Math.min(totalPages - 1, currentPage + 1); i++) pages.push(i);
      if (currentPage < totalPages - 2) pages.push("ellipsis");
      pages.push(totalPages);
    }
    return pages;
  }, [currentPage, totalPages]);

  // Loading state
  if (isLoading) {
    return (
      <DashboardLayout>
        <div className="space-y-6" data-testid="loading-skeleton">
          <div>
            <Skeleton className="h-7 w-32" />
            <Skeleton className="h-5 w-24 mt-1" />
          </div>
          <Skeleton className="h-12 w-72" />
          <Skeleton className="h-64" />
        </div>
      </DashboardLayout>
    );
  }

  // Error state
  if (error) {
    return (
      <DashboardLayout>
        <div className="space-y-6">
          <div>
            <h2 className="text-xl font-bold text-foreground">交易历史</h2>
            <p className="text-sm text-muted-foreground mt-1">交易记录</p>
          </div>
          <Alert variant="destructive" data-testid="error-alert">
            <AlertCircle className="h-4 w-4" />

